-- =====================================================================
-- LiPi HIS — India Geodata Seed
-- States/UTs, Districts, Cities for clinic DB reference tables
-- Source: github.com/sab99r/Indian-States-And-Districts (MIT license),
--         India Post Office data, NITI Aayog ADP list
-- Run after 01_core_v3.sql
-- =====================================================================

SET search_path = core, public;

-- Countries seed
ON CONFLICT (code) DO NOTHING;

-- States & Union Territories
ON CONFLICT (code) DO NOTHING;

-- Districts
ON CONFLICT (state_id, name) DO NOTHING;

-- Cities
ON CONFLICT (district_id, name) DO NOTHING;

-- Verify
SELECT 'States: ' || count(*) FROM core.states;
SELECT 'Districts: ' || count(*) FROM core.districts;
SELECT 'Aspirational districts: ' || count(*) FROM core.districts WHERE is_aspirational;
SELECT 'Cities: ' || count(*) FROM core.cities;